//! Records the pinned Engineering Assurance revision.
//!
//! The E02 public-contract wire types (`e02_contracts.rs`) and the retained
//! shared-reference `wire_v1`/`wire_v2` types (`shared_reference_v1.rs`, `shared_reference_v2.rs`)
//! are generated by public crate `quire-verification-contracts` (PLAT-861, VER-50), which this
//! crate depends on and re-exports at `contracts`.

use std::error::Error;
use std::fs;

fn main() -> Result<(), Box<dyn Error>> {
    println!("cargo:rerun-if-changed=Cargo.toml");
    println!(
        "cargo:rustc-env=ENGINEERING_ASSURANCE_REVISION={}",
        engineering_assurance_revision()?
    );
    Ok(())
}

fn engineering_assurance_revision() -> Result<String, Box<dyn Error>> {
    let manifest = fs::read_to_string("Cargo.toml")?;
    let manifest = manifest.parse::<toml::Table>()?;
    let revision = manifest
        .get("dependencies")
        .and_then(toml::Value::as_table)
        .and_then(|dependencies| dependencies.get("engineering-assurance"))
        .and_then(toml::Value::as_table)
        .and_then(|dependency| dependency.get("rev"))
        .and_then(toml::Value::as_str)
        .ok_or("Engineering Assurance dependency must declare a revision")?;
    if revision.len() != 40
        || !revision
            .bytes()
            .all(|byte| byte.is_ascii_digit() || matches!(byte, b'a'..=b'f'))
    {
        return Err("Engineering Assurance dependency revision is not a full commit".into());
    }
    Ok(revision.to_owned())
}
